242	     * @param lastName the owner's last name (already validated non-blank)
243	     * @return the formatted customer code for the owner being created
244	     */
245	    private String nextCustomerCode(String lastName) {
246	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
