261	    /**
262	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
263	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
264	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
265	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
266	     * {@code "+61412345678"}.
267	     *
268	     * @param telephone the raw telephone value from the request
269	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
270	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
271	     */
272	    private static String normalizeTelephone(String telephone) {
273	        String e164 = toE164(telephone);
274	        if (e164 == null) {
275	            throw new InvalidFieldValueException("telephone",
276	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
277	        }
278	        return e164;
279	    }
280	
281	    /**
282	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
283	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
284	     * owners' stored numbers when detecting duplicates.
285	     */
286	    private static String toE164(String telephone) {
287	        if (telephone == null) {
288	            return null;
289	        }
290	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
291	        String digits;
292	        if (cleaned.startsWith("+")) {
293	            digits = cleaned.substring(1);
294	        } else {
295	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
296	            digits = "61" + national;
297	        }
298	        if (!digits.matches("[0-9]{8,15}")) {
299	            return null;
300	        }
301	        return "+" + digits;
302	    }
303	
304	    /**
305	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
306	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
307	     *
308	     * @param email the raw email value from the request (already known to be non-null)
309	     * @return the lower-cased email to be stored and returned
310	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
311	     */
312	    private static String normalizeEmail(String email) {
313	        String trimmed = email.trim();
314	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
315	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
316	        }
317	        return trimmed.toLowerCase(Locale.ROOT);
318	    }
319	
320	    /**
321	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
322	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
323	     *
324	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
325	     * @throws DuplicateTelephoneException if another owner already uses this telephone
326	     */
327	    private void requireUniqueTelephone(String normalizedTelephone) {
328	        boolean taken = this.clinicService.findAllOwners().stream()
329	            .map(Owner::getTelephone)
330	            .map(OwnerRestControllerV1::toE164)
331	            .filter(existing -> existing != null)
332	            .anyMatch(normalizedTelephone::equals);
333	        if (taken) {
334	            throw new DuplicateTelephoneException(normalizedTelephone);
335	        }
336	    }
