544	
545	    /**
546	     * Handles exception thrown by Bean Validation on controller methods parameters
547	     *
548	     * @param e The {@link MethodArgumentNotValidException} to be handled
549	     * @param request {@link HttpServletRequest} object referring to the current request.
550	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
551	     */
552	    @ExceptionHandler(MethodArgumentNotValidException.class)
553	    @ResponseBody
554	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
555	        HttpStatus status = HttpStatus.BAD_REQUEST;
556	        BindingErrorsResponse errors = new BindingErrorsResponse();
557	        BindingResult bindingResult = e.getBindingResult();
558	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
559	        if (bindingResult.hasErrors()) {
560	            errors.addAllErrors(bindingResult);
561	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
562	                .map(fieldError -> {
563	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
564	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
565	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
566	                        fieldError.getField(),
567	                        defaultMessage,
568	                        rejectedValue);
569	                    return new ValidationMessageDto(message)
570	                        .putAdditionalProperty("field", fieldError.getField())
571	                        .putAdditionalProperty("rejectedValue", rejectedValue)
572	                        .putAdditionalProperty("defaultMessage", defaultMessage);
573	                })
574	                .toList();
575	            logger.debug("Validation error at {} {}: {}",
576	                request.getMethod(),
577	                request.getRequestURI(),
578	                bindingResult.getFieldErrors());
579	            List<String> errorFields = bindingResult.getFieldErrors().stream()
580	                .map(FieldError::getField)
581	                .distinct()
582	                .toList();
583	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
584	            detail.setProperty("errors", errorFields);
585	            return ResponseEntity.status(status).body(detail);
586	        }
587	        return ResponseEntity.status(status).body(detail);
588	    }
589	
590	    /**
591	     * Handles {@link MissingRequiredFieldsException} raised when a request omits or leaves blank one
592	     * or more required fields. Returns a 400 Bad Request whose body carries an {@code errors} array
593	     * listing the name of each offending field.
594	     *
595	     * @param e The {@link MissingRequiredFieldsException} to be handled
596	     * @param request {@link HttpServletRequest} object referring to the current request.
597	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
598	     */
599	    @ExceptionHandler(MissingRequiredFieldsException.class)
600	    @ResponseBody
601	    public ResponseEntity<ProblemDetail> handleMissingRequiredFieldsException(MissingRequiredFieldsException e, HttpServletRequest request) {
602	        HttpStatus status = HttpStatus.BAD_REQUEST;
603	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
604	        detail.setProperty("errors", e.getFields());
605	        logger.debug("Missing required fields at {} {}: {}",
606	            request.getMethod(),
607	            request.getRequestURI(),
608	            e.getFields());
609	        return ResponseEntity.status(status).body(detail);
610	    }
611	
612	    /**
613	     * Handles {@link InvalidFieldValueException} raised when a request supplies a field whose value
614	     * is present but violates a business rule (for example a telephone number that is not exactly
615	     * ten digits after stripping non-digit characters). Returns a 400 Bad Request whose body carries
616	     * an {@code errors} array listing the name of each offending field.
617	     *
618	     * @param e The {@link InvalidFieldValueException} to be handled
619	     * @param request {@link HttpServletRequest} object referring to the current request.
620	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
621	     */
622	    @ExceptionHandler(InvalidFieldValueException.class)
623	    @ResponseBody
624	    public ResponseEntity<ProblemDetail> handleInvalidFieldValueException(InvalidFieldValueException e, HttpServletRequest request) {
625	        HttpStatus status = HttpStatus.BAD_REQUEST;
626	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
627	        detail.setProperty("errors", e.getFields());
628	        logger.debug("Invalid field value at {} {}: {}",
629	            request.getMethod(),
630	            request.getRequestURI(),
631	            e.getFields());
632	        return ResponseEntity.status(status).body(detail);
633	    }
634	
635	    /**
636	     * Handles {@link DuplicateTelephoneException} raised when a request attempts to create an owner
637	     * whose normalized telephone number is already used by another owner. Returns a 409 Conflict
638	     * whose body carries an {@code errors} array naming the offending field.
639	     *
640	     * @param e The {@link DuplicateTelephoneException} to be handled
641	     * @param request {@link HttpServletRequest} object referring to the current request.
642	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
643	     */
644	    @ExceptionHandler(DuplicateTelephoneException.class)
645	    @ResponseBody
646	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
647	        HttpStatus status = HttpStatus.CONFLICT;
648	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
649	        detail.setProperty("errors", e.getFields());
650	        logger.debug("Duplicate telephone at {} {}: {}",
651	            request.getMethod(),
652	            request.getRequestURI(),
653	            e.getFields());
654	        return ResponseEntity.status(status).body(detail);
655	    }
